const fmt=new Intl.NumberFormat('en-US');
function escCSV(value){const s=String(value??'');return /[",\n]/.test(s)?'"'+s.replaceAll('"','""')+'"':s}
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function safeGet(key){try{return localStorage.getItem(key)}catch(_){return null}}
function safeSet(key,value){try{localStorage.setItem(key,value)}catch(_){}}
function readStoredArray(key){try{const value=JSON.parse(safeGet(key)||'[]');return Array.isArray(value)?value.filter(v=>typeof v==='string'):[]}catch(_){return []}}
function titleCaseStatus(key){return key==='stray'?'Occasional visitor':key==='both'?'Known + visitor notes':'Known from Texas'}
function friendlyCategory(value){const map={Butterfly:'Butterfly',Skipper:'Skipper butterfly',Macromoth:'Larger moth',Micromoth:'Small moth'};return map[value]||value||'Butterfly or moth'}
function friendlyCommonName(value){let s=String(value||'No common name listed').replace(/^\?+\s*/,'').trim();s=s.replace(/^\[|\]$/g,'').replace(/\s+applied to\s+.*$/i,'').trim();return s||'No common name listed'}
const HOST_SEARCH_STOP_WORDS=new Set(['plant','plants','tree','trees','shrub','shrubs','flower','flowers','grass','grasses','vine','vines','genus','species']);
function normalizeHostText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ')}
function normalizeHostQuery(value){const raw=normalizeHostText(value),tokens=raw.split(' ').filter(Boolean),useful=tokens.filter(token=>!HOST_SEARCH_STOP_WORDS.has(token));return (useful.length?useful:tokens).join(' ')}
function pluralVariants(value){const text=normalizeHostText(value);if(!text)return[];const out=new Set([text]);text.split(' ').forEach(word=>{if(word.endsWith('ies')&&word.length>4)out.add(text.replace(new RegExp(`${word}$`),word.slice(0,-3)+'y'));else if(word.endsWith('s')&&word.length>3&&!word.endsWith('ss'))out.add(text.replace(new RegExp(`${word}$`),word.slice(0,-1))) });return[...out]}
function limitedEditDistance(a,b,max){if(Math.abs(a.length-b.length)>max)return max+1;let previous=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const current=[i];let rowMin=i;for(let j=1;j<=b.length;j++){const cost=a[i-1]===b[j-1]?0:1;const value=Math.min(current[j-1]+1,previous[j]+1,previous[j-1]+cost);current[j]=value;if(value<rowMin)rowMin=value}if(rowMin>max)return max+1;previous=current}return previous[b.length]}
function hostTermScore(query,term){if(!query||!term)return Infinity;if(term===query)return 0;if(term.startsWith(query))return 10+(term.length-query.length)/100;const words=term.split(' ');if(words.includes(query))return 18;if(words.some(word=>word.startsWith(query)))return 24;if(term.includes(query))return 32+(term.indexOf(query)/100);const queryWords=query.split(' ');if(queryWords.length>1){let total=0;for(const qWord of queryWords){let best=Infinity;for(const word of words){if(word===qWord)best=Math.min(best,0);else if(word.startsWith(qWord))best=Math.min(best,2);else if(word.includes(qWord))best=Math.min(best,5);else if(qWord.length>=4&&word[0]===qWord[0]){const limit=qWord.length>8?2:1;const distance=limitedEditDistance(qWord,word,limit);if(distance<=limit)best=Math.min(best,8+distance)}}if(!Number.isFinite(best))return Infinity;total+=best}return 36+total}if(query.length<4)return Infinity;const limit=query.length>12?3:query.length>6?2:1;let bestDistance=Infinity;const candidates=[term,...words];for(const candidate of candidates){if(candidate[0]!==query[0]||Math.abs(candidate.length-query.length)>limit)continue;bestDistance=Math.min(bestDistance,limitedEditDistance(query,candidate,limit))}return bestDistance<=limit?50+bestDistance:Infinity}
const HOST_SEARCH_INDEX=hosts.map(host=>{const genus=host.genus,common=POPULAR_HOST_NAMES[genus]||'',aliases=HOST_SEARCH_ALIASES[genus]||[];const terms=[];[genus,common,...aliases].forEach(value=>pluralVariants(value).forEach(term=>{if(term&&!terms.includes(term))terms.push(term)}));return{host,genus,common,aliases,terms,scientific:normalizeHostText(genus)}});
function scoreHostIndex(item,query){const normalized=normalizeHostQuery(query);if(!normalized)return{score:0,matchedTerm:'',kind:'all'};const first=normalized.split(' ')[0];if(item.scientific===first&&normalized!==first)return{score:4,matchedTerm:item.genus,kind:'scientific species'};let score=Infinity,matchedTerm='',kind='';for(const term of item.terms){const candidate=hostTermScore(normalized,term);if(candidate<score){score=candidate;matchedTerm=term;kind=term===item.scientific?'scientific name':(item.aliases.some(alias=>normalizeHostText(alias)===term)?'alternate common name':'common name')}}return{score,matchedTerm,kind}}
function rankHostMatches(query,limit=Infinity){const normalized=normalizeHostQuery(query);let rows=HOST_SEARCH_INDEX.map(item=>({...item,...scoreHostIndex(item,normalized)})).filter(item=>Number.isFinite(item.score));const alpha=$('hostSort')&&$('hostSort').value==='alpha';rows.sort((a,b)=>a.score-b.score||(alpha?a.genus.localeCompare(b.genus):b.host.establishedCount-a.host.establishedCount||b.host.totalCount-a.host.totalCount||a.genus.localeCompare(b.genus)));return Number.isFinite(limit)?rows.slice(0,limit):rows}
function exactHostName(value){const normalized=normalizeHostQuery(value);if(!normalized)return'';const first=normalized.split(' ')[0],scientific=HOST_SEARCH_INDEX.find(item=>item.scientific===first);if(scientific&&(normalized===first||normalized.split(' ').length>1))return scientific.genus;const matches=rankHostMatches(normalized,2);return matches.length&&matches[0].score<1&&(matches.length===1||matches[1].score>matches[0].score)?matches[0].genus:''}
const hostSuggestionState={matches:[],active:-1};
function hostDisplayCommon(genus){return POPULAR_HOST_NAMES[genus]||''}
function appendHighlightedText(target,text,query){const raw=String(text||''),needle=String(query||'').trim();if(!needle){target.textContent=raw;return}const index=raw.toLowerCase().indexOf(needle.toLowerCase());if(index<0){target.textContent=raw;return}target.append(document.createTextNode(raw.slice(0,index)));const mark=document.createElement('mark');mark.textContent=raw.slice(index,index+needle.length);target.append(mark,document.createTextNode(raw.slice(index+needle.length)))}
function closeHostSuggestions(){const menu=$('hostSearchSuggestions'),input=$('hostSearch');if(!menu||!input)return;menu.hidden=true;input.setAttribute('aria-expanded','false');input.setAttribute('aria-activedescendant','');hostSuggestionState.active=-1}
function setActiveHostSuggestion(index){const menu=$('hostSearchSuggestions');if(!menu||!hostSuggestionState.matches.length)return;hostSuggestionState.active=(index+hostSuggestionState.matches.length)%hostSuggestionState.matches.length;menu.querySelectorAll('[role=option]').forEach((option,i)=>{const active=i===hostSuggestionState.active;option.setAttribute('aria-selected',active?'true':'false');if(active){$('hostSearch').setAttribute('aria-activedescendant',option.id);option.scrollIntoView({block:'nearest'})}})}
function selectHostSuggestion(index,{jump=false}={}){const match=hostSuggestionState.matches[index];if(!match)return;$('hostSearch').value=match.genus;syncHostSearchUI();closeHostSuggestions();state.hostPage=1;renderHosts();if(jump)setTimeout(()=>$('hostResultsPanel').scrollIntoView({behavior:'smooth',block:'start'}),50);else $('hostSearch').focus()}
function renderHostSuggestions(){const input=$('hostSearch'),menu=$('hostSearchSuggestions');if(!input||!menu)return;syncHostSearchUI();const query=input.value.trim();if(normalizeHostQuery(query).length<2){closeHostSuggestions();return}hostSuggestionState.matches=rankHostMatches(query,8);hostSuggestionState.active=-1;menu.replaceChildren();if(!hostSuggestionState.matches.length){menu.append(node('div','smart-search-empty','No close plant-name match found. Try fewer letters or browse the filtered results below.'));menu.hidden=false;input.setAttribute('aria-expanded','true');return}hostSuggestionState.matches.forEach((match,index)=>{const option=node('button','smart-search-option');option.type='button';option.id=`hostSearchSuggestion-${index}`;option.setAttribute('role','option');option.setAttribute('aria-selected','false');const names=node('span','smart-search-name'),common=hostDisplayCommon(match.genus);if(common){const commonLine=node('span','smart-search-common');appendHighlightedText(commonLine,common,query);const scientific=node('span','smart-search-scientific');appendHighlightedText(scientific,match.genus,query);names.append(commonLine,scientific)}else{const scientific=node('span','smart-search-common');scientific.style.fontStyle='italic';appendHighlightedText(scientific,match.genus,query);names.append(scientific,node('span','smart-search-scientific','Scientific plant genus'))}const normalizedQuery=normalizeHostQuery(query),matched=String(match.matchedTerm||'');if(match.score>=50){names.append(node('span','smart-search-match','Close spelling match'))}else if(matched&&matched!==normalizeHostText(match.genus)&&matched!==normalizeHostText(common)&&matched!==normalizedQuery){names.append(node('span','smart-search-match',`Matched ${match.kind}: “${matched}”`))}const count=node('span','smart-search-count');count.append(node('strong','',fmt.format(match.host.establishedCount)),node('span','','Texas-range taxa'));option.append(names,count);option.addEventListener('pointerdown',event=>event.preventDefault());option.addEventListener('click',()=>selectHostSuggestion(index));menu.append(option)});menu.hidden=false;input.setAttribute('aria-expanded','true')}
function syncHostSearchUI(){const clear=$('clearHostSearch');if(clear)clear.hidden=!$('hostSearch').value}
function switchTab(tab){document.querySelectorAll('.tab').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');b.tabIndex=active?0:-1});document.querySelectorAll('.view').forEach(v=>{const active=v.id==='view-'+tab;v.classList.toggle('active',active);v.setAttribute('aria-hidden',active?'false':'true')});if(tab==='garden')renderGarden();if(tab==='compare')renderComparison();if(tab==='local'){if(localState.rows.length)renderLocalScanResults();setTimeout(()=>localMap&&localMap.invalidateSize(),120)}window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
document.querySelector('.tabs').addEventListener('keydown',event=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;const tabs=[...document.querySelectorAll('.tab')],current=tabs.indexOf(document.activeElement);if(current<0)return;event.preventDefault();let next=current;if(event.key==='ArrowRight')next=(current+1)%tabs.length;if(event.key==='ArrowLeft')next=(current-1+tabs.length)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;tabs[next].focus();switchTab(tabs[next].dataset.tab)});
document.querySelectorAll('[data-tab-target]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tabTarget)));
