  $('heroHostSearchForm').addEventListener('submit',event=>{event.preventDefault();if(hostSuggestionState.active>=0&&!$('hostSearchSuggestions').hidden){selectHostSuggestion(hostSuggestionState.active,{jump:true});return}closeHostSuggestions();switchTab('hosts');state.hostPage=1;renderHosts();setTimeout(()=>$('hostResultsPanel').scrollIntoView({behavior:'smooth',block:'start'}),50)});
  $('hostPrev').addEventListener('click',()=>{if(state.hostPage>1){state.hostPage--;renderHostCards()}});$('hostNext').addEventListener('click',()=>{if(state.hostPage<hostPageCount()){state.hostPage++;renderHostCards()}});
