  $('surpriseHost').addEventListener('click',surprisePlant);$('surpriseHostToolbar').addEventListener('click',surprisePlant);$('gardenSurprise').addEventListener('click',surprisePlant);$('compareSurprise').addEventListener('click',()=>addToComparison(randomSurpriseGenus()));
