  $('gardenInsectSearch').addEventListener('input',renderGardenInsectList);$('gardenInsectType').addEventListener('change',renderGardenInsectList);$('gardenInsectSort').addEventListener('change',renderGardenInsectList);$('exportGardenInsects').addEventListener('click',exportGardenInsectCSV);
  $('modalClose').addEventListener('click',closeModal);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal()});document.addEventListener('click',e=>{if(!$('hostGenusCombo').contains(e.target))closeHostGenusMenu()});document.addEventListener('keydown',e=>{const modalOpen=$('modalBackdrop').classList.contains('open');if(modalOpen&&e.key==='Tab'){const focusable=[...$('modalBackdrop').querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled&&el.offsetParent!==null);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(e.key==='Escape'&&!$('hostGenusMenu').hidden){closeHostGenusMenu();return}if(e.key==='Escape'&&modalOpen)closeModal()});
