function makeGardenButton(genus,small=false){const button=node('button','button'+(small?' small':'')+' garden-toggle',gardenPlants.has(genus)?'Saved ✓':'Save to My Garden');button.type='button';button.dataset.genus=genus;if(gardenPlants.has(genus))button.classList.add('saved');button.addEventListener('click',e=>{e.stopPropagation();toggleGarden(genus)});return button}
