function renderGarden(){if(!$('gardenGrid'))return;const saved=[...gardenPlants].filter(g=>hosts.some(h=>h.genus===g)).sort((a,b)=>hostInfo(b).establishedCount-hostInfo(a).establishedCount||a.localeCompare(b));const union=new Map();saved.forEach(g=>recordsForHost(g).forEach(r=>union.set(r.id,r)));const all=[...union.values()],butterflies=all.filter(r=>['Butterfly','Skipper'].includes(r.category)).length;const top=saved.slice().sort((a,b)=>hostInfo(b).establishedCount-hostInfo(a).establishedCount)[0];const kpis=[['Saved plants',fmt.format(saved.length),'Plant groups in My Garden'],['Unique linked taxa',fmt.format(all.length),'Across all saved plants'],['Butterflies & skippers',fmt.format(butterflies),'Moths are counted separately'],['Top connector',top||'—',top?fmt.format(hostInfo(top).establishedCount)+' Texas-range taxa':'Save a plant to begin']];$('gardenKpis').replaceChildren(...kpis.map(([a,b,c])=>{const x=node('div','kpi');x.append(node('div','kpi-label',a),node('div','kpi-value',b),node('div','kpi-note',c));return x}));const grid=$('gardenGrid');grid.replaceChildren();if(!saved.length){const empty=node('div','garden-empty');empty.style.gridColumn='1/-1';empty.append(node('h2','','Your garden list is empty'),node('p','','Save an oak, milkweed, willow, or any other plant group. Your combined insect totals will appear here.'));const add=node('button','button primary','Find a host plant');add.addEventListener('click',()=>switchTab('hosts'));empty.append(add);grid.append(empty)}else saved.forEach(g=>grid.append(makePlantCollectionCard(g,{removable:true})));const recommendations=hosts.filter(h=>!gardenPlants.has(h.genus)&&h.establishedCount>0).sort((a,b)=>Number(Boolean(POPULAR_HOST_NAMES[b.genus]))-Number(Boolean(POPULAR_HOST_NAMES[a.genus]))||b.establishedCount-a.establishedCount).slice(0,3);const rec=$('gardenRecommendations');rec.replaceChildren(...recommendations.map(h=>makePlantCollectionCard(h.genus,{recommendation:true})));renderGardenInsectList();observePendingThumbnails($('view-garden'));observePendingNativeBadges($('view-garden'));persistGarden()}


function gardenInsectEntries(){const saved=[...gardenPlants].filter(g=>hosts.some(h=>h.genus===g));const merged=new Map();saved.forEach(genus=>recordsForHost(genus).forEach(record=>{let entry=merged.get(record.id);if(!entry){entry={record,plants:new Set()};merged.set(record.id,entry)}entry.plants.add(genus)}));return [...merged.values()].map(entry=>({record:entry.record,plants:[...entry.plants].sort((a,b)=>a.localeCompare(b))}))}
