function setupNativeStatusObserver(){if(!('IntersectionObserver' in window))return;nativeStatusObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){nativeStatusObserver.unobserve(entry.target);loadNativeStatusBadge(entry.target)}}),{rootMargin:'140px'})}
function makeNativeBadge(genus){const badge=node('span','native-badge checking','Checking Texas status…');badge.dataset.nativeGenus=genus;badge.title='Live genus-level status from the iNaturalist Texas checklist. Individual species can differ.';return badge}
