async function getTexasPlaceId(){const stored=Number(safeGet('txlep-texas-place-id'));if(stored)return stored;if(texasPlaceIdPromise)return texasPlaceIdPromise;texasPlaceIdPromise=(async()=>{const response=await fetch('https://api.inaturalist.org/v1/places/autocomplete?q=Texas&per_page=20',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Texas place lookup failed');const data=await response.json();const place=(data.results||[]).find(p=>String(p.display_name||'').toLowerCase()==='texas, us')||(data.results||[]).find(p=>String(p.name||'').toLowerCase()==='texas');if(!place)throw new Error('Texas place not found');safeSet('txlep-texas-place-id',String(place.id));return place.id})();return texasPlaceIdPromise}
async function fetchTexasPlantStatus(genus){if(nativeStatusCache.has(genus))return nativeStatusCache.get(genus);const stored=safeGet('txlep-native-'+genus);if(stored){try{const parsed=JSON.parse(stored);nativeStatusCache.set(genus,parsed);return parsed}catch(_){}}const placeId=await getTexasPlaceId();const params=new URLSearchParams({q:genus,rank:'genus',per_page:'10',preferred_place_id:String(placeId)});const response=await fetch('https://api.inaturalist.org/v1/taxa/autocomplete?'+params.toString(),{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Plant status service unavailable');const data=await response.json();const taxon=(data.results||[]).find(t=>String(t.name||'').toLowerCase()===genus.toLowerCase());const raw=String((taxon&&taxon.preferred_establishment_means)||(taxon&&taxon.establishment_means&&taxon.establishment_means.establishment_means)||'').toLowerCase();let status;if(raw==='native'||raw==='endemic')status={key:'native',label:'Includes Texas-native species'};else if(raw==='introduced')status={key:'introduced',label:'Texas checklist: introduced'};else status={key:'unknown',label:'Texas native status not confirmed'};status.href=taxon&&taxon.id?`https://www.inaturalist.org/taxa/${taxon.id}`:`https://www.inaturalist.org/taxa/search?q=${encodeURIComponent(genus)}`;nativeStatusCache.set(genus,status);safeSet('txlep-native-'+genus,JSON.stringify(status));return status}
async function loadNativeStatusBadge(badge){if(badge.dataset.loaded)return;badge.dataset.loaded='1';const genus=badge.dataset.nativeGenus;try{const status=await fetchTexasPlantStatus(genus);badge.className='native-badge '+status.key;badge.textContent=status.label;const link=document.createElement('a');link.className=badge.className;link.textContent=badge.textContent;link.href=status.href;link.target='_blank';link.rel='noopener';link.title='Genus-level status from the iNaturalist Texas checklist. Individual species can differ.';link.addEventListener('click',e=>e.stopPropagation());for(const attr of [...badge.attributes]){if(attr.name.startsWith('data-'))link.setAttribute(attr.name,attr.value)}badge.replaceWith(link)}catch(_){badge.className='native-badge offline';badge.textContent='Texas status available online'}}


