function localTaxonKey(value){const cleaned=String(value||'').replace(/[\[\](){}]/g,' ').replace(/\s+/g,' ').trim();const match=cleaned.match(/\b([A-Z][A-Za-z-]+)\s+([a-z][A-Za-z-]+)\b/);return match?`${match[1]} ${match[2]}`.toLowerCase():''}
