function pointInPolygon(lat,lng,vertices){let inside=false;for(let i=0,j=vertices.length-1;i<vertices.length;j=i++){const xi=vertices[i].lng,yi=vertices[i].lat,xj=vertices[j].lng,yj=vertices[j].lat;const intersect=((yi>lat)!=(yj>lat))&&(lng<(xj-xi)*(lat-yi)/(yj-yi+Number.EPSILON)+xi);if(intersect)inside=!inside}return inside}
