function applyResourceFilters(){
  const q=$('resourceSearch').value.trim().toLowerCase(),type=$('resourceTypeFilter').value,status=$('resourceStatusFilter').value;state.filteredResources=records.filter(r=>{if(!(r.otherResources||[]).length)return false;if(status==='established'&&!['established','both'].includes(r.statusKey))return false;if(status==='stray'&&r.statusKey!=='stray')return false;if(status==='both'&&r.statusKey!=='both')return false;if(type&&!r.otherResources.includes(type))return false;if(q&&!r._resourceSearch.includes(q))return false;return true});const max=resourcePageCount();if(state.resourcePage>max)state.resourcePage=Math.max(1,max);renderResourceTable()
}
function resourcePageCount(){return Math.max(1,Math.ceil(state.filteredResources.length/state.resourcePageSize))}
